ANCHOR = "@media(max-width:1100px){.shp .pg{grid-template-columns:repeat(3,1fr)}}"


def apply(h):
    if "function openP" in h or OLD_ART not in h or OLD_ADD not in h:
        return h
    h = h.replace(OLD_ART, NEW_ART, 1).replace(OLD_ADD, NEW_ADD, 1)
    return h.replace(ANCHOR, CSS + ANCHOR, 1) if ANCHOR in h else h.replace("</style>", CSS + "</style>", 1)
